window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2ce46c17cdf8d8dd"]={"versions": [{"id": "FIG-2ce46c17cdf8d8dd", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Ausschnitt des AUTOSAR M2-Metamodells (<em>BSW Module Description Template</em>, <code>BswInternalBehavior</code>).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung des internen Verhaltens von BSW-Modulen (Basic Software) in der AUTOSAR Classic Platform.</li>\n<li><strong>Architektur-Zweck:</strong> Definition der Trigger-Kopplung zwischen Modul-Ereignissen (<code>BswEvent</code>) und den ausführbaren C-Funktionen (<code>BswModuleEntity</code>). Bildet die formale Grundlage für die Konfiguration des Schedule Managers (SchM), die OS-Task-Abbildung sowie die Multicore-Allokation von BSW-Funktionen gemäß <em>AUTOSAR BSW Distribution Guide</em>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Wurzel & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswInternalBehavior</code></strong> (Spezialisierung von <code>InternalBehavior</code>): Zentraler Container für die Verhaltensbeschreibung einer BSW-Modulinstanz.</li>\n<li><strong><code>«atpVariation»</code></strong>: Kennzeichnet Variationspunkte (AUTOSAR Template Profile). Sowohl Events (<code>+event [0..<em>]</code>) als auch Entities (<code>+entity [1..</em>]</code>) können über Pre-Compile- oder Post-Build-Conditions variantenabhängig eingebunden werden.</li>\n</ul>\n<p class=\"fig-p\">#### Event-Hierarchie (Generalisierung von <code>AbstractEvent</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswEvent</code></strong>: Abstrakte Basisklasse aller BSW-Ereignisse.</li>\n<li><strong><code>BswOperationInvokedEvent</code></strong>: Löst die synchrone oder asynchrone Abarbeitung bei Eintreffen eines Operationsaufrufs (Client-Server / API) aus.</li>\n<li><strong><code>BswScheduleEvent</code></strong> (<em>kursiv / abstrakt</em>): Basisklasse für alle periodischen oder ereignisgesteuerten Trigger, die über den BSW Scheduler (SchM) in Betriebssystem-Tasks disponiert werden.</li>\n<li><strong><code>BswTimingEvent</code></strong>: Zyklischer Trigger; spezifiziert über das Attribut <code>period : TimeValue</code> (z. B. für periodische Main-Functions).</li>\n<li><strong><code>BswBackgroundEvent</code></strong>: Niedrigstpriorer Trigger zur Ausführung in Leerlaufphasen (Background-Task).</li>\n<li><strong><code>BswExternalTriggerOccurredEvent</code></strong>: Getriggert durch externe Hard- oder Peripherie-Interrupts/Trigger.</li>\n<li><strong><code>BswInternalTriggerOccurredEvent</code></strong>: BSW-interner Software-Trigger zwischen Modulfunktionen.</li>\n<li><strong><code>BswModeSwitchEvent</code></strong>: Zustandsänderungs-Trigger (vom BswM gesteuert); besitzt Attribut <code>activation : ModeActivationKind</code> (<code>ON_ENTRY</code>, <code>ON_EXIT</code>, <code>ON_TRANSITION</code>).</li>\n<li><strong><code>BswModeSwitchedAckEvent</code></strong>: Rückmeldung / Acknowledge über einen abgeschlossenen Mode-Switch.</li>\n<li><strong><code>BswModeManagerErrorEvent</code></strong>: Fehler-Trigger bei gescheiterten Mode-Transitionen.</li>\n<li><strong><code>BswDataReceivedEvent</code></strong>: Trigger bei Verfügbarkeit neuer Kommunikationsdaten (Sender-Receiver).</li>\n<li><strong><code>BswAsynchronousServerCallReturnsEvent</code></strong>: Callback-Event bei Fertigstellung eines asynchronen Server-Aufrufs.</li>\n</ul>\n<p class=\"fig-p\">#### Entity-Hierarchie (Generalisierung von <code>ExecutableEntity</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswModuleEntity</code></strong>: Abstrakter Basistyp für ausführbaren C-Code eines BSW-Moduls.</li>\n<li><strong><code>BswCalledEntity</code></strong>: Repräsentiert direkt/synchron per Funktionsaufruf aufgerufene Modul-APIs.</li>\n<li>Assoziation: <code>startsOnEvent [1]</code> verweist auf <code>BswOperationInvokedEvent</code>.</li>\n<li><strong><code>BswSchedulableEntity</code></strong>: Repräsentiert Scheduler-verwaltete C-Funktionen (z. B. <code>&lt;Mod&gt;_MainFunction</code>).</li>\n<li>Assoziation: <code>startsOnEvent [1]</code> verweist auf <code>BswScheduleEvent</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Synchrone Ausführungspfad (<code>BswCalledEntity</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Ein externer Caller (SWC via RTE oder anderes BSW-Modul) ruft eine BSW-Schnittstelle auf.</li>\n<li><strong>Dispatch:</strong> Entspricht semantisch einem <code>BswOperationInvokedEvent</code>.</li>\n<li><strong>Kontext:</strong> Der Aufruf wird unmittelbar im Thread/Task-Kontext des Aufrufers synchron ausgeführt (kein Task-Wechsel, sofern sender- und empfängerseitige Partitionen/Cores identisch sind; andernfalls Weiterleitung über Inter-OS-Application- bzw. Inter-Core-Stubs).</li>\n</ol>\n<p class=\"fig-p\">#### Scheduler-gesteuerter Ausführungspfad (<code>BswSchedulableEntity</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger-Erzeugung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zeitablauf (OS-Counter/Alarm) feuert <code>BswTimingEvent</code>.</li>\n<li>Zustandstransition im BswM feuert <code>BswModeSwitchEvent</code>.</li>\n<li>Empfang von I-PDUs / Daten feuert <code>BswDataReceivedEvent</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>SchM-Dispatching:</strong> Der RTE/SchM fängt das Event ab und aktiviert die zugeordnete OS-Task (<code>ActivateTask</code> oder <code>SetEvent</code>).</li>\n<li><strong>Execution:</strong> Im Kontext der OS-Task ruft der SchM die konfigurierte C-Funktion der <code>BswSchedulableEntity</code> (<code>&lt;Mod&gt;_MainFunction</code>) auf.</li>\n<li><strong>Asynchrone Rückmeldung:</strong> Nach asynchronen Diensten wird <code>BswAsynchronousServerCallReturnsEvent</code> erzeugt, um die Fortsetzung im SchM-Kontext zu triggern.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Konfiguration (ARXML):</strong></li>\n<li>Für jede Modul-Main-Function (<code>Can_MainFunction_Write</code>, <code>Com_MainFunctionRx</code> etc.) muss zwingend eine <code>BswSchedulableEntity</code> mit passendem <code>BswScheduleEvent</code> (typischerweise <code>BswTimingEvent</code> mit <code>period</code>) deklariert werden.</li>\n<li>Standard-Modul-APIs (<code>Can_Write</code>, <code>Com_SendSignal</code>) sind als <code>BswCalledEntity</code> zu modellieren.</li>\n<li><strong>SchM- und OS-Task-Mapping:</strong></li>\n<li>Der RTE/SchM-Generator nutzt <code>startsOnEvent</code>, um <code>BswSchedulableEntities</code> in generierte SchM-Tasks einzubetten.</li>\n<li>Unpräzise Perioden (<code>TimeValue</code>) oder unvollständige Mode-Aktivierungen (<code>ModeActivationKind</code>) führen zu Timing-Jitter, Deadline-Verletzungen oder fehlenden Modus-Umschaltungen.</li>\n<li><strong>Multicore- & BSW-Distribution:</strong></li>\n<li><code>BswSchedulableEntities</code> können flexibel auf Cores/OS-Applications verteilt werden.</li>\n<li><code>BswCalledEntities</code> erfordern bei Core-übergreifenden Zugriffen zwingend Cross-Core-Mechanismen (z. B. IOC – <em>Inter-OS-Application Communicator</em> oder RPC-Stubs des SchM).</li>\n<li><strong>Konkurrierender Zugriff & Reentrancy:</strong></li>\n<li>Teilt sich eine <code>BswCalledEntity</code> oder <code>BswSchedulableEntity</code> Daten mit anderen Entities, müssen im <code>BswInternalBehavior</code> korrespondierende <code>BswExclusiveArea</code>-Definitionen hinterlegt werden, die der SchM in OS-Interrupt-Sperren (<code>SuspendAllInterrupts</code>) oder Spinlocks auflöst.</li>\n</ul>"}, {"id": "FIG-9e6cab765c891833", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Ausschnitt des AUTOSAR M2-Metamodells (<em>BSW Module Description Template</em>, <code>BswInternalBehavior</code>).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung des internen Verhaltens von BSW-Modulen (Basic Software) in der AUTOSAR Classic Platform.</li>\n<li><strong>Architektur-Zweck:</strong> Definition der Trigger-Kopplung zwischen Modul-Ereignissen (<code>BswEvent</code>) und den ausführbaren C-Funktionen (<code>BswModuleEntity</code>). Bildet die formale Grundlage für die Konfiguration des Schedule Managers (SchM), die OS-Task-Abbildung sowie die Multicore-Allokation von BSW-Funktionen gemäß <em>AUTOSAR BSW Distribution Guide</em>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Wurzel & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswInternalBehavior</code></strong> (Spezialisierung von <code>InternalBehavior</code>): Zentraler Container für die Verhaltensbeschreibung einer BSW-Modulinstanz.</li>\n<li><strong><code>«atpVariation»</code></strong>: Kennzeichnet Variationspunkte (AUTOSAR Template Profile). Sowohl Events (<code>+event [0..<em>]</code>) als auch Entities (<code>+entity [1..</em>]</code>) können über Pre-Compile- oder Post-Build-Conditions variantenabhängig eingebunden werden.</li>\n</ul>\n<p class=\"fig-p\">#### Event-Hierarchie (Generalisierung von <code>AbstractEvent</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswEvent</code></strong>: Abstrakte Basisklasse aller BSW-Ereignisse.</li>\n<li><strong><code>BswOperationInvokedEvent</code></strong>: Löst die synchrone oder asynchrone Abarbeitung bei Eintreffen eines Operationsaufrufs (Client-Server / API) aus.</li>\n<li><strong><code>BswScheduleEvent</code></strong> (<em>kursiv / abstrakt</em>): Basisklasse für alle periodischen oder ereignisgesteuerten Trigger, die über den BSW Scheduler (SchM) in Betriebssystem-Tasks disponiert werden.</li>\n<li><strong><code>BswTimingEvent</code></strong>: Zyklischer Trigger; spezifiziert über das Attribut <code>period : TimeValue</code> (z. B. für periodische Main-Functions).</li>\n<li><strong><code>BswBackgroundEvent</code></strong>: Niedrigstpriorer Trigger zur Ausführung in Leerlaufphasen (Background-Task).</li>\n<li><strong><code>BswExternalTriggerOccurredEvent</code></strong>: Getriggert durch externe Hard- oder Peripherie-Interrupts/Trigger.</li>\n<li><strong><code>BswInternalTriggerOccurredEvent</code></strong>: BSW-interner Software-Trigger zwischen Modulfunktionen.</li>\n<li><strong><code>BswModeSwitchEvent</code></strong>: Zustandsänderungs-Trigger (vom BswM gesteuert); besitzt Attribut <code>activation : ModeActivationKind</code> (<code>ON_ENTRY</code>, <code>ON_EXIT</code>, <code>ON_TRANSITION</code>).</li>\n<li><strong><code>BswModeSwitchedAckEvent</code></strong>: Rückmeldung / Acknowledge über einen abgeschlossenen Mode-Switch.</li>\n<li><strong><code>BswModeManagerErrorEvent</code></strong>: Fehler-Trigger bei gescheiterten Mode-Transitionen.</li>\n<li><strong><code>BswDataReceivedEvent</code></strong>: Trigger bei Verfügbarkeit neuer Kommunikationsdaten (Sender-Receiver).</li>\n<li><strong><code>BswAsynchronousServerCallReturnsEvent</code></strong>: Callback-Event bei Fertigstellung eines asynchronen Server-Aufrufs.</li>\n</ul>\n<p class=\"fig-p\">#### Entity-Hierarchie (Generalisierung von <code>ExecutableEntity</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswModuleEntity</code></strong>: Abstrakter Basistyp für ausführbaren C-Code eines BSW-Moduls.</li>\n<li><strong><code>BswCalledEntity</code></strong>: Repräsentiert direkt/synchron per Funktionsaufruf aufgerufene Modul-APIs.</li>\n<li>Assoziation: <code>startsOnEvent [1]</code> verweist auf <code>BswOperationInvokedEvent</code>.</li>\n<li><strong><code>BswSchedulableEntity</code></strong>: Repräsentiert Scheduler-verwaltete C-Funktionen (z. B. <code>&lt;Mod&gt;_MainFunction</code>).</li>\n<li>Assoziation: <code>startsOnEvent [1]</code> verweist auf <code>BswScheduleEvent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Synchrone Ausführungspfad (<code>BswCalledEntity</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Ein externer Caller (SWC via RTE oder anderes BSW-Modul) ruft eine BSW-Schnittstelle auf.</li>\n<li><strong>Dispatch:</strong> Entspricht semantisch einem <code>BswOperationInvokedEvent</code>.</li>\n<li><strong>Kontext:</strong> Der Aufruf wird unmittelbar im Thread/Task-Kontext des Aufrufers synchron ausgeführt (kein Task-Wechsel, sofern sender- und empfängerseitige Partitionen/Cores identisch sind; andernfalls Weiterleitung über Inter-OS-Application- bzw. Inter-Core-Stubs).</li>\n</ol>\n<p class=\"fig-p\">#### Scheduler-gesteuerter Ausführungspfad (<code>BswSchedulableEntity</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger-Erzeugung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zeitablauf (OS-Counter/Alarm) feuert <code>BswTimingEvent</code>.</li>\n<li>Zustandstransition im BswM feuert <code>BswModeSwitchEvent</code>.</li>\n<li>Empfang von I-PDUs / Daten feuert <code>BswDataReceivedEvent</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>SchM-Dispatching:</strong> Der RTE/SchM fängt das Event ab und aktiviert die zugeordnete OS-Task (<code>ActivateTask</code> oder <code>SetEvent</code>).</li>\n<li><strong>Execution:</strong> Im Kontext der OS-Task ruft der SchM die konfigurierte C-Funktion der <code>BswSchedulableEntity</code> (<code>&lt;Mod&gt;_MainFunction</code>) auf.</li>\n<li><strong>Asynchrone Rückmeldung:</strong> Nach asynchronen Diensten wird <code>BswAsynchronousServerCallReturnsEvent</code> erzeugt, um die Fortsetzung im SchM-Kontext zu triggern.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Konfiguration (ARXML):</strong></li>\n<li>Für jede Modul-Main-Function (<code>Can_MainFunction_Write</code>, <code>Com_MainFunctionRx</code> etc.) muss zwingend eine <code>BswSchedulableEntity</code> mit passendem <code>BswScheduleEvent</code> (typischerweise <code>BswTimingEvent</code> mit <code>period</code>) deklariert werden.</li>\n<li>Standard-Modul-APIs (<code>Can_Write</code>, <code>Com_SendSignal</code>) sind als <code>BswCalledEntity</code> zu modellieren.</li>\n<li><strong>SchM- und OS-Task-Mapping:</strong></li>\n<li>Der RTE/SchM-Generator nutzt <code>startsOnEvent</code>, um <code>BswSchedulableEntities</code> in generierte SchM-Tasks einzubetten.</li>\n<li>Unpräzise Perioden (<code>TimeValue</code>) oder unvollständige Mode-Aktivierungen (<code>ModeActivationKind</code>) führen zu Timing-Jitter, Deadline-Verletzungen oder fehlenden Modus-Umschaltungen.</li>\n<li><strong>Multicore- & BSW-Distribution:</strong></li>\n<li><code>BswSchedulableEntities</code> können flexibel auf Cores/OS-Applications verteilt werden.</li>\n<li><code>BswCalledEntities</code> erfordern bei Core-übergreifenden Zugriffen zwingend Cross-Core-Mechanismen (z. B. IOC – <em>Inter-OS-Application Communicator</em> oder RPC-Stubs des SchM).</li>\n<li><strong>Konkurrierender Zugriff & Reentrancy:</strong></li>\n<li>Teilt sich eine <code>BswCalledEntity</code> oder <code>BswSchedulableEntity</code> Daten mit anderen Entities, müssen im <code>BswInternalBehavior</code> korrespondierende <code>BswExclusiveArea</code>-Definitionen hinterlegt werden, die der SchM in OS-Interrupt-Sperren (<code>SuspendAllInterrupts</code>) oder Spinlocks auflöst.</li>\n</ul>"}, {"id": "FIG-58a6a4b0bcd76f12", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Ausschnitt des AUTOSAR M2-Metamodells (<em>BSW Module Description Template</em>, <code>BswInternalBehavior</code>).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung des internen Verhaltens von BSW-Modulen (Basic Software) in der AUTOSAR Classic Platform.</li>\n<li><strong>Architektur-Zweck:</strong> Definition der Trigger-Kopplung zwischen Modul-Ereignissen (<code>BswEvent</code>) und den ausführbaren C-Funktionen (<code>BswModuleEntity</code>). Bildet die formale Grundlage für die Konfiguration des Schedule Managers (SchM), die OS-Task-Abbildung sowie die Multicore-Allokation von BSW-Funktionen gemäß <em>AUTOSAR BSW Distribution Guide</em>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Wurzel & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswInternalBehavior</code></strong> (Spezialisierung von <code>InternalBehavior</code>): Zentraler Container für die Verhaltensbeschreibung einer BSW-Modulinstanz.</li>\n<li><strong><code>«atpVariation,atpSplitable»</code></strong>: Beide Kompositionen (<code>+event [0..<em>]</code> und <code>+entity [0..</em>]</code>) sind als variant (<code>«atpVariation»</code>) sowie splitbar über mehrere ARXML-Dateien (<code>«atpSplitable»</code>) deklariert.</li>\n<li>*<em>Kardinalität <code>+entity [0..</em>]</code>**: Entitäten sind optional; erlaubt leere Verhaltensbeschreibungen oder reine Event-Definitionen.</li>\n</ul>\n<p class=\"fig-p\">#### Event-Hierarchie (Generalisierung von <code>AbstractEvent</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswEvent</code></strong>: Abstrakte Basisklasse aller BSW-Ereignisse.</li>\n<li>Assoziation: <code>+startsOnEvent [0..1]</code> verbindet <code>BswEvent</code> direkt mit <code>BswModuleEntity</code>.</li>\n<li><strong>Direkte Spezialisierungen von <code>BswEvent</code>:</strong></li>\n<li><strong><code>BswOperationInvokedEvent</code></strong>: Trigger bei Eintreffen eines Operationsaufrufs (Client-Server / API).</li>\n<li><strong><code>BswInterruptEvent</code></strong>: Trigger für Interrupt-Service-Routinen (CAT1 / CAT2 ISRs).</li>\n<li><strong><code>BswScheduleEvent</code></strong> (<em>kursiv / abstrakt</em>): Basisklasse für alle Scheduler-verwalteten Trigger.</li>\n<li><strong>Spezialisierungen von <code>BswScheduleEvent</code>:</strong></li>\n<li><strong><code>BswTimingEvent</code></strong>: Zyklischer Trigger; Attribut <code>period : TimeValue [0..1]</code>.</li>\n<li><strong><code>BswBackgroundEvent</code></strong>: Trigger für Leerlauf-/Hintergrund-Tasks.</li>\n<li><strong><code>BswExternalTriggerOccurredEvent</code></strong>: Trigger durch externe Hardware- oder Peripherie-Ereignisse.</li>\n<li><strong><code>BswInternalTriggerOccurredEvent</code></strong>: BSW-interner Software-Trigger zwischen Modulfunktionen.</li>\n<li><strong><code>BswModeSwitchEvent</code></strong>: Trigger bei Moduswechseln; Attribut <code>activation : ModeActivationKind [0..1]</code>.</li>\n<li><strong><code>BswModeSwitchedAckEvent</code></strong>: Acknowledge-Rückmeldung eines vollzogenen Moduswechsels.</li>\n<li><strong><code>BswModeManagerErrorEvent</code></strong>: Fehler-Trigger bei fehlgeschlagenen Modusübergängen.</li>\n<li><strong><code>BswDataReceivedEvent</code></strong>: Trigger bei Eingang neuer Kommunikationsdaten.</li>\n<li><strong><code>BswAsynchronousServerCallReturnsEvent</code></strong>: Callback-Trigger bei Rückkehr eines asynchronen Server-Calls.</li>\n<li><strong><code>BswOsTaskExecutionEvent</code></strong>: Trigger gekoppelt an die Aktivierung/Abarbeitung einer OS-Task.</li>\n</ul>\n<p class=\"fig-p\">#### Entity-Hierarchie (Generalisierung von <code>ExecutableEntity</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswModuleEntity</code></strong>: Abstrakter Basistyp für ausführbaren C-Code eines BSW-Moduls; Ziel der <code>+startsOnEvent [0..1]</code>-Assoziation von <code>BswEvent</code>.</li>\n<li><strong><code>BswCalledEntity</code></strong>: Repräsentiert direkt/synchron per API aufgerufene Modulfunktionen.</li>\n<li><strong><code>BswSchedulableEntity</code></strong>: Repräsentiert Scheduler-verwaltete C-Funktionen (z. B. Main-Functions).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Generisches Event-zu-Entity-Dispatching</p>\n<ol class=\"fig-list\">\n<li><strong>Triggerung:</strong> Ein beliebiges <code>BswEvent</code> tritt auf.</li>\n<li><strong>Kopplung via <code>startsOnEvent</code>:</strong> Über die generalisierte Assoziation <code>+startsOnEvent [0..1]</code> wird direkt die zugehörige <code>BswModuleEntity</code> aktiviert.</li>\n</ol>\n<p class=\"fig-p\">#### Ausführungspfade nach Entitätstyp</p>\n<ul class=\"fig-list\">\n<li><strong>Synchrone Ausführung (<code>BswCalledEntity</code>):</strong> Typischerweise ausgelöst durch <code>BswOperationInvokedEvent</code>; läuft unmittelbar im Thread-/Task-Kontext des Aufrufers ab.</li>\n<li><strong>Scheduler-basierte Ausführung (<code>BswSchedulableEntity</code>):</strong> Ausgelöst durch Spezialisierungen von <code>BswScheduleEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code> oder <code>BswOsTaskExecutionEvent</code>); Zuweisung und Aktivierung erfolgen über den Schedule Manager (SchM) in einer OS-Task.</li>\n<li><strong>Interrupt-Abarbeitung (<code>BswInterruptEvent</code>):</strong> Ausführung im ISR-Kontext (CAT1/CAT2) bei Hardware-Ereignissen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Refaktorisierung:</strong> Die Assoziation <code>startsOnEvent</code> wurde von den konkreten Subtypen (<code>BswCalledEntity</code>, <code>BswSchedulableEntity</code>) auf die abstrakten Basisebenen <code>BswEvent</code> und <code>BswModuleEntity</code> gehoben. Dadurch wird die Trigger-Beziehung metamodellweit vereinheitlicht und die Kardinalität an der Entity auf <code>0..1</code> gesetzt.</li>\n<li><strong>ARXML-Splitting (<code>«atpSplitable»</code>):</strong> Die Stereotypisierung der Kompositionen <code>+event</code> und <code>+entity</code> mit <code>«atpSplitable»</code> ermöglicht die Aufteilung von BSW-Verhaltensbeschreibungen über separate ARXML-Dateien, was die Arbeitsteiligkeit bei Multi-Core- und Multi-Partner-Projekten wesentlich unterstützt.</li>\n<li><strong>Entfall der Entitäts-Mindestanzahl:</strong> Die Änderung der unteren Kardinalität von <code>entity</code> von <code>1..<em></code> auf <code>0..</em></code> erlaubt valide <code>BswInternalBehavior</code>-Beschreibungen ohne vorab definierte Entitäten (z. B. in frühen Phasen der Systemdefinition).</li>\n<li><strong>Erweiterte Event-Typen:</strong> Mit <code>BswInterruptEvent</code> und <code>BswOsTaskExecutionEvent</code> können ISR-Trigger und dedizierte OS-Task-Aktivierungen im BSW-Modell formal abgebildet und konfiguriert werden.</li>\n<li><strong>Attribut-Kardinalitäten:</strong> Die Attribute <code>period</code> (<code>BswTimingEvent</code>) und <code>activation</code> (<code>BswModeSwitchEvent</code>) tragen nun explizit die Multiplizität <code>[0..1]</code>.</li>\n</ul>"}, {"id": "FIG-5fcc33901e7f0997", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Ausschnitt des AUTOSAR M2-Metamodells (<em>BSW Module Description Template</em>, <code>BswInternalBehavior</code>).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung des internen Verhaltens von BSW-Modulen (Basic Software) in der AUTOSAR Classic Platform.</li>\n<li><strong>Architektur-Zweck:</strong> Definition der Trigger-Kopplung zwischen Modul-Ereignissen (<code>BswEvent</code>) und den ausführbaren C-Funktionen (<code>BswModuleEntity</code>). Bildet die formale Grundlage für die Konfiguration des Schedule Managers (SchM), die OS-Task-Abbildung sowie die Multicore-Allokation von BSW-Funktionen gemäß <em>AUTOSAR BSW Distribution Guide</em>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Wurzel & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswInternalBehavior</code></strong> (Spezialisierung von <code>InternalBehavior</code>): Zentraler Container für die Verhaltensbeschreibung einer BSW-Modulinstanz.</li>\n<li><strong><code>«atpVariation,atpSplitable»</code></strong>: Beide Kompositionen (<code>+event [0..<em>]</code> und <code>+entity [0..</em>]</code>) sind als variant (<code>«atpVariation»</code>) sowie splitbar über mehrere ARXML-Dateien (<code>«atpSplitable»</code>) deklariert.</li>\n<li>*<em>Kardinalität <code>+entity [0..</em>]</code>**: Entitäten sind optional; erlaubt leere Verhaltensbeschreibungen oder reine Event-Definitionen.</li>\n</ul>\n<p class=\"fig-p\">#### Event-Hierarchie (Generalisierung von <code>AbstractEvent</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswEvent</code></strong>: Abstrakte Basisklasse aller BSW-Ereignisse.</li>\n<li>Assoziation: <code>+startsOnEvent [0..1]</code> verbindet <code>BswEvent</code> direkt mit <code>BswModuleEntity</code>.</li>\n<li><strong>Direkte Spezialisierungen von <code>BswEvent</code>:</strong></li>\n<li><strong><code>BswOperationInvokedEvent</code></strong>: Trigger bei Eintreffen eines Operationsaufrufs (Client-Server / API).</li>\n<li><strong><code>BswInterruptEvent</code></strong>: Trigger für Interrupt-Service-Routinen (CAT1 / CAT2 ISRs).</li>\n<li><strong><code>BswScheduleEvent</code></strong> (<em>kursiv / abstrakt</em>): Basisklasse für alle Scheduler-verwalteten Trigger.</li>\n<li><strong>Spezialisierungen von <code>BswScheduleEvent</code>:</strong></li>\n<li><strong><code>BswTimingEvent</code></strong>: Zyklischer Trigger; Attribut <code>period : TimeValue [0..1]</code>.</li>\n<li><strong><code>BswBackgroundEvent</code></strong>: Trigger für Leerlauf-/Hintergrund-Tasks.</li>\n<li><strong><code>BswExternalTriggerOccurredEvent</code></strong>: Trigger durch externe Hardware- oder Peripherie-Ereignisse.</li>\n<li><strong><code>BswInternalTriggerOccurredEvent</code></strong>: BSW-interner Software-Trigger zwischen Modulfunktionen.</li>\n<li><strong><code>BswModeSwitchEvent</code></strong>: Trigger bei Moduswechseln; Attribut <code>activation : ModeActivationKind [0..1]</code>.</li>\n<li><strong><code>BswModeSwitchedAckEvent</code></strong>: Acknowledge-Rückmeldung eines vollzogenen Moduswechsels.</li>\n<li><strong><code>BswModeManagerErrorEvent</code></strong>: Fehler-Trigger bei fehlgeschlagenen Modusübergängen.</li>\n<li><strong><code>BswDataReceivedEvent</code></strong>: Trigger bei Eingang neuer Kommunikationsdaten.</li>\n<li><strong><code>BswAsynchronousServerCallReturnsEvent</code></strong>: Callback-Trigger bei Rückkehr eines asynchronen Server-Calls.</li>\n<li><strong><code>BswOsTaskExecutionEvent</code></strong>: Trigger gekoppelt an die Aktivierung/Abarbeitung einer OS-Task.</li>\n</ul>\n<p class=\"fig-p\">#### Entity-Hierarchie (Generalisierung von <code>ExecutableEntity</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswModuleEntity</code></strong>: Abstrakter Basistyp für ausführbaren C-Code eines BSW-Moduls; Ziel der <code>+startsOnEvent [0..1]</code>-Assoziation von <code>BswEvent</code>.</li>\n<li><strong><code>BswCalledEntity</code></strong>: Repräsentiert direkt/synchron per API aufgerufene Modulfunktionen.</li>\n<li><strong><code>BswSchedulableEntity</code></strong>: Repräsentiert Scheduler-verwaltete C-Funktionen (z. B. Main-Functions).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Generisches Event-zu-Entity-Dispatching</p>\n<ol class=\"fig-list\">\n<li><strong>Triggerung:</strong> Ein beliebiges <code>BswEvent</code> tritt auf.</li>\n<li><strong>Kopplung via <code>startsOnEvent</code>:</strong> Über die generalisierte Assoziation <code>+startsOnEvent [0..1]</code> wird direkt die zugehörige <code>BswModuleEntity</code> aktiviert.</li>\n</ol>\n<p class=\"fig-p\">#### Ausführungspfade nach Entitätstyp</p>\n<ul class=\"fig-list\">\n<li><strong>Synchrone Ausführung (<code>BswCalledEntity</code>):</strong> Typischerweise ausgelöst durch <code>BswOperationInvokedEvent</code>; läuft unmittelbar im Thread-/Task-Kontext des Aufrufers ab.</li>\n<li><strong>Scheduler-basierte Ausführung (<code>BswSchedulableEntity</code>):</strong> Ausgelöst durch Spezialisierungen von <code>BswScheduleEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code> oder <code>BswOsTaskExecutionEvent</code>); Zuweisung und Aktivierung erfolgen über den Schedule Manager (SchM) in einer OS-Task.</li>\n<li><strong>Interrupt-Abarbeitung (<code>BswInterruptEvent</code>):</strong> Ausführung im ISR-Kontext (CAT1/CAT2) bei Hardware-Ereignissen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Refaktorisierung:</strong> Die Assoziation <code>startsOnEvent</code> wurde von den konkreten Subtypen (<code>BswCalledEntity</code>, <code>BswSchedulableEntity</code>) auf die abstrakten Basisebenen <code>BswEvent</code> und <code>BswModuleEntity</code> gehoben. Dadurch wird die Trigger-Beziehung metamodellweit vereinheitlicht und die Kardinalität an der Entity auf <code>0..1</code> gesetzt.</li>\n<li><strong>ARXML-Splitting (<code>«atpSplitable»</code>):</strong> Die Stereotypisierung der Kompositionen <code>+event</code> und <code>+entity</code> mit <code>«atpSplitable»</code> ermöglicht die Aufteilung von BSW-Verhaltensbeschreibungen über separate ARXML-Dateien, was die Arbeitsteiligkeit bei Multi-Core- und Multi-Partner-Projekten wesentlich unterstützt.</li>\n<li><strong>Entfall der Entitäts-Mindestanzahl:</strong> Die Änderung der unteren Kardinalität von <code>entity</code> von <code>1..<em></code> auf <code>0..</em></code> erlaubt valide <code>BswInternalBehavior</code>-Beschreibungen ohne vorab definierte Entitäten (z. B. in frühen Phasen der Systemdefinition).</li>\n<li><strong>Erweiterte Event-Typen:</strong> Mit <code>BswInterruptEvent</code> und <code>BswOsTaskExecutionEvent</code> können ISR-Trigger und dedizierte OS-Task-Aktivierungen im BSW-Modell formal abgebildet und konfiguriert werden.</li>\n<li><strong>Attribut-Kardinalitäten:</strong> Die Attribute <code>period</code> (<code>BswTimingEvent</code>) und <code>activation</code> (<code>BswModeSwitchEvent</code>) tragen nun explizit die Multiplizität <code>[0..1]</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-2ce46c17cdf8d8dd", "to": "FIG-9e6cab765c891833", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9e6cab765c891833", "to": "FIG-58a6a4b0bcd76f12", "fr": "R19-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>BswInternalBehavior</code>: Stereotyp beider Kompositionen (<code>+event</code> und <code>+entity</code>) von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.</li>\n<li><code>BswInternalBehavior</code>: Kardinalität der Komposition <code>+entity</code> von <code>1..<em></code> auf <code>0..</em></code> gelockert.</li>\n<li><code>BswEvent</code> / <code>BswModuleEntity</code>: Die Assoziation <code>startsOnEvent</code> wurde von den konkreten Subtypen auf die Basisebene gehoben und verbindet nun <code>BswEvent</code> mit <code>BswModuleEntity</code> als gerichtete Assoziation <code>+startsOnEvent</code> mit Kardinalität <code>0..1</code> (vorher getrennte Assoziationen <code>startsOnEvent [1]</code> an <code>BswCalledEntity</code> und <code>BswSchedulableEntity</code>).</li>\n<li><code>BswEvent</code>: Neue Spezialisierung <code>BswInterruptEvent</code> ergänzt.</li>\n<li><code>BswScheduleEvent</code>: Neue Spezialisierung <code>BswOsTaskExecutionEvent</code> ergänzt.</li>\n<li><code>BswTimingEvent</code>: Attribut <code>period : TimeValue</code> explizit mit Kardinalität <code>[0..1]</code> versehen.</li>\n<li><code>BswModeSwitchEvent</code>: Attribut <code>activation : ModeActivationKind</code> explizit mit Kardinalität <code>[0..1]</code> versehen.</li>\n<li>Layout: Zweispaltige Neuordnung der Spezialisierungen von <code>BswScheduleEvent</code>.</li>\n</ul>"}, {"from": "FIG-58a6a4b0bcd76f12", "to": "FIG-5fcc33901e7f0997", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
